const form=document.getElementById("contractForm"),printArea=document.getElementById("printArea"),printBtn=document.getElementById("printBtn"),printHint=document.getElementById("printHint");form&&form.addEventListener("submit",e=>{e.preventDefault();const n=new FormData(form),t=d=>(n.get(d)||"").trim(),r=t("city"),o=t("date"),s=t("execName"),p=t("execDetails"),i=t("clientName"),c=t("clientDetails"),a=t("subject"),g=t("price"),l=t("term");printArea.innerHTML=`
      <div style="text-align:center;font-size:19px;letter-spacing:1.5px;margin-bottom:18px">ДОГОВОР ОКАЗАНИЯ УСЛУГ</div>
      <div style="display:flex;justify-content:space-between;margin-bottom:16px;font-size:14px"><span>г. ${esc(r)}</span><span>«${esc(o)}»</span></div>
      <p><strong>${esc(s)}</strong>, именуемый(ая) в дальнейшем «Исполнитель», с одной стороны, и <strong>${esc(i)}</strong>, именуемый(ая) в дальнейшем «Заказчик», с другой стороны, заключили настоящий Договор о нижеследующем:</p>
      <p><strong>1. Предмет договора.</strong> Исполнитель обязуется оказать следующие услуги: ${esc(a)}.</p>
      <p><strong>2. Стоимость услуг.</strong> Стоимость услуг составляет <strong>${esc(g)} ₽</strong>.</p>
      <p><strong>3. Срок оказания.</strong> Услуги оказываются в течение: <strong>${esc(l)}</strong>.</p>
      <p><strong>4. Реквизиты сторон.</strong><br>Исполнитель: ${esc(s)}, ${esc(p)}.<br>Заказчик: ${esc(i)}, ${esc(c)}.</p>
      <p style="margin-top:48px;display:flex;justify-content:space-between"><span>Исполнитель ____________</span><span>Заказчик ____________</span></p>
    `,printBtn&&(printBtn.disabled=!1),printHint&&(printHint.hidden=!1),printBtn.focus()}),printBtn&&printBtn.addEventListener("click",()=>window.print());function esc(e){return e.replace(/[&<>"']/g,n=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[n])}
